  await page.locator('.file-actions button').first.click();await check(await page.evaluate('__sent.at(-1).action==="artifactSave"&&__sent.at(-1).data.id==="'+('d'*32)+'"'),'file save uses artifact id');await page.locator('.file-actions button').nth(1).click();await check(await page.evaluate('__sent.at(-1).action==="artifactCopy"'),'file copy wired')
