  image='data:image/png;base64,'+base64.b64encode((OUT/'chat-desktop.png').read_bytes()).decode();withimage=copy.deepcopy(fixture);withimage['current']['messages'][1]['artifacts']=[{'id':'e'*32,'name':'Снимок интерфейса.png','bytes':120000,'kind':'image','dataUrl':image}];await page.evaluate('(d)=>receive({type:"state",data:d})',withimage);await check(await page.locator('.result-file img').count()==1,'PNG shown inline')
