  await page.evaluate('(d)=>receive({type:"state",data:d})',fixture);await page.evaluate('receive({type:"busy",data:true})');await check(await page.locator('#access-btn').is_disabled() and await page.locator('.file-actions button').first.is_disabled(),'permissions and file actions locked while busy');await page.evaluate('receive({type:"busy",data:false})');await page.set_viewport_size({'width':390,'height':844});await check(await page.evaluate('document.documentElement.scrollWidth===innerWidth'),'mobile no horizontal overflow');await page.locator('#access-btn').click();await check(await page.locator('#access-save').is_visible(),'mobile access dialog scrollable');await check(not errors,'no JavaScript exceptions')
